//! Scènes originales ; chaque chapitre comprend quatre quartiers/épreuves.
#[derive(Clone, Copy)]
pub struct Chapter { pub title: &'static str, pub lines: [&'static str; 4], pub place: Place }
#[derive(Clone, Copy, PartialEq, Debug)]
pub enum Place { City, Arena, Sewers, Factory, Archives, Gardens, Palace, Red, Void }

pub const CHAPTERS: [Chapter; 25] = [
 Chapter {title:"LE CONTRAT DORÉ",place:Place::City,lines:["Le dieu du Capitalisme vous engage : sauver la cité.","Il promet du pain et des remèdes pour les quartiers pauvres.","En échange, vous devrez atteindre son ennemi juré.","Une voix dans la foule vous met en garde : lisez les contrats."]},
 Chapter {title:"L'ARÈNE DES DETTES",place:Place::Arena,lines:["Votre premier guide, Sélène, vous conduit à l'arène.","Les vainqueurs obtiennent un laissez-passer ; les perdants, une dette.","Votre rival combat pour payer le traitement de sa sœur.","Jouez le duel contre l'ordinateur ou choisissez un second joueur."]},
 Chapter {title:"LE PONT DES OUBLIÉS",place:Place::City,lines:["Sélène cherche son frère, disparu après une visite au palais.","Elle vous montre les quartiers laissés sans eau depuis des mois.","Pour franchir le pont, trouvez les sceaux et repoussez les créatures.","Un garde prétend que la pénurie est un sacrifice nécessaire."]},
 Chapter {title:"LES ÉGOUTS VERTS",place:Place::Sewers,lines:["Sous les rues, une ancienne guérisseuse soigne les habitants.","Elle vous apprend la flamme verte, un feu qui repousse les ombres.","Elle refuse l'or du dieu : ses remèdes étaient autrefois gratuits.","Désormais, même l'eau propre porte le sceau d'une compagnie."]},
 Chapter {title:"LES FAILLES DU MÉTRO",place:Place::Sewers,lines:["Les tunnels effondrés mènent au vieux réseau de transport.","Sautez les failles : elles s'étendent du nord au sud.","Des ouvriers murmurent que les travaux furent arrêtés exprès.","Leur indemnité a financé un nouvel immeuble du dieu."]},
 Chapter {title:"L'USINE DES PROMESSES",place:Place::Factory,lines:["Les machines fabriquent des coffres plutôt que des remèdes.","Sélène découvre une liste de travailleurs endettés à vie.","On vous assure qu'il s'agit seulement d'une erreur de comptabilité.","Traversez les ateliers et récupérez les premiers registres."]},
 Chapter {title:"LE QUARTIER DES CENDRES",place:Place::City,lines:["Un incendie a détruit les maisons de ceux qui refusaient de partir.","Le terrain appartient désormais à une filiale du palais.","Une enfant a conservé une copie de l'ordre d'évacuation.","Votre employeur appelle cela une amélioration urbaine."]},
 Chapter {title:"LE JARDIN SOUS VERROU",place:Place::Gardens,lines:["Derrière les grilles pousse la nourriture promise aux pauvres.","La garde réserve pourtant les récoltes aux investisseurs.","Libérez le passage pour qu'un convoi puisse atteindre la ville.","Sélène : « Pourquoi priver de nourriture ceux qu'il dit protéger ? »"]},
 Chapter {title:"LE PRIX D'UN REMÈDE",place:Place::Factory,lines:["Une pharmacie exige un contrat perpétuel contre un seul remède.","Son sceau est celui du dieu qui vous emploie.","Le rival de l'arène a disparu après avoir signé.","Sélène : « Aidons les vivants. L'or ne rendra pas sa liberté. »"]},
 Chapter {title:"LA BIBLIOTHÈQUE SCELLÉE",place:Place::Archives,lines:["Les archives cachent la version effacée de la guerre des dieux.","Le Capitalisme finançait les deux armées par des intermédiaires.","Chaque victoire lui permettait de réclamer davantage de sacrifices.","Des pages ont été déchirées : cherchez-les dans les salles."]},
 Chapter {title:"LE TRAIN BRISÉ",place:Place::Sewers,lines:["Un train conduisait les débiteurs vers une destination inconnue.","Ses rails traversent une seconde série de failles.","Sautez et retrouvez les dossiers perdus dans les wagons.","Sur la dernière feuille apparaît le nom du frère de Sélène."]},
 Chapter {title:"LA DETTE DES VIVANTS",place:Place::City,lines:["Le frère de Sélène travaillait pour rembourser des frais inventés.","Il a été emmené lorsqu'il a réclamé les comptes de l'usine.","Un ancien garde vous indique les caves du palais.","Avant d'y aller, il vous confie un carnet taché de rouge."]},
 Chapter {title:"L'ÉCOLE DES MARÉES",place:Place::Red,lines:["Dans le carnet, une survivante décrit la vague de sang.","Ce pouvoir ne vous appartient pas par naissance : vous l'apprenez.","Il traverse plusieurs ennemis sur sa trajectoire.","La survivante demande une chose : ne l'utilisez pas contre les civils."]},
 Chapter {title:"LES PONTS DE FER",place:Place::Factory,lines:["Le dieu annonce une grande victoire avant même votre arrivée.","Ses agents rachètent les maisons proches du front à bas prix.","La guerre n'est plus un accident : elle est devenue son marché.","Une note secrète vous conduit vers la tour des contrats."]},
 Chapter {title:"LA TOUR DES CONTRATS",place:Place::Palace,lines:["Vous entrez dans la tour où les promesses deviennent des dettes.","Certains contrats sont signés par des personnes déjà disparues.","Sélène copie les registres pour les remettre aux habitants.","L'alarme résonne : votre employeur sait que vous cherchez la vérité."]},
 Chapter {title:"LE TÉMOIN INVISIBLE",place:Place::Archives,lines:["Un témoin affirme avoir vu le frère de Sélène dans les caves.","Il a découvert une dette fictive imposée à toute une génération.","Le palais l'a effacé des registres, mais pas de la mémoire des siens.","Rassemblez les sceaux nécessaires pour ouvrir la porte basse."]},
 Chapter {title:"LES CAVES DU PALAIS",place:Place::Palace,lines:["Les cachots sont vides, mais des traces récentes traversent les murs.","Son frère a écrit : « Sélène, ne paie plus ma dette. »", "Il a fui avec d'autres prisonniers vers le quartier rouge.","La garde du dieu vous accuse maintenant de vol."]},
 Chapter {title:"LE MARCHÉ DES OMBRES",place:Place::City,lines:["Les habitants échangent des vivres sans passer par le palais.","Le dieu a envoyé ses gardes fermer ce marché libre.","Protégez les passages et trouvez les documents confisqués.","Sélène : « Ils appellent cela la paix, mais en vendent le prix. »"]},
 Chapter {title:"LA ROUTE ROUGE",place:Place::Red,lines:["Le territoire du Communisme n'est pas le refuge espéré.","Ses patrouilles arrêtent quiconque questionne leur chef.","Sélène retrouve la trace de son frère parmi les fugitifs.","Entre deux puissances, les habitants cherchent simplement à vivre."]},
 Chapter {title:"LE PACTE DÉCHIRÉ",place:Place::Archives,lines:["Vous retrouvez le frère de Sélène, vivant mais affaibli.","Il possède l'original d'un pacte signé par les deux dieux.","Ils ont entretenu leur rivalité pour gouverner par la peur.","Le Communisme a trahi le pacte ; le Capitalisme vous a envoyé le punir."]},
 Chapter {title:"LA DERNIÈRE CARAVANE",place:Place::Gardens,lines:["Les témoins doivent porter le pacte jusqu'à la cité.","Frayez-leur un chemin à travers les gardes des deux camps.","Une réserve de soins a été laissée dans chaque quartier.","Votre employeur promet encore une récompense, mais exige le silence."]},
 Chapter {title:"LES PORTES DU TRÔNE",place:Place::Red,lines:["Le trône rouge se dresse derrière les dernières défenses.","Des captifs vous demandent d'arrêter leur dieu, pas de les remplacer.","Les registres montrent que ses purges ont brisé des familles entières.","Il ne reste qu'à traverser les salles et atteindre le sanctuaire."]},
 Chapter {title:"LE DIEU DU COMMUNISME",place:Place::Red,lines:["Le dieu du Communisme refuse de rendre des comptes.","Il appelle ses gardes et lance des vagues de sang en éventail.","Sélène et son frère emportent les preuves pendant le combat.","Vaincre ce dieu achèvera le contrat initial."]},
 Chapter {title:"LE SALAIRE DU SILENCE",place:Place::Palace,lines:["Le Capitalisme exige maintenant les registres et votre silence.","Il admet avoir vendu de faux remèdes et créé des dettes fictives.","Sa récompense : devenir son bras armé, loin des regards.","Les habitants attendent votre décision au pied du palais."]},
 Chapter {title:"LA DETTE DU CAPITAL",place:Place::Void,lines:["Vous refusez de lui livrer Sélène, son frère et les preuves.","Le dieu du Capitalisme se bat lui-même pour protéger sa fortune.","Il arrache des immeubles à la ville et lance des pièces brûlantes.","Vainquez votre ancien employeur pour rendre les comptes au peuple."]},
];
